import { VERBATIM_SOURCE } from './source-guidance.js';
import { z } from 'zod';
import { KANVAS_VERSION } from './version.js';

export const HELP_TOPICS=['flashcards','notifications','diagnostics','about','what-is-kanvas','tour','orientation','submit','planner','navigation','sharing','comparison','iframe','regional','templates','recovery','agent-workflow','reading','task-updates','invitations','account-start','install-and-cast','work-views','selection','accounts-and-teams','activity-history','session-topology','json-explorer','shared-pointing','images','feedback'] as const;
export type HelpTopic=typeof HELP_TOPICS[number];
export const helpInputSchema=z.object({topic:z.enum(HELP_TOPICS).default('orientation'),question:z.string().max(1500).optional(),sessionId:z.string().min(1).max(128).optional(),displayId:z.string().min(1).max(128).optional()}).strict().refine(x=>!x.displayId||Boolean(x.sessionId),'A displayId needs its sessionId.');
export const TOUR_GUIDANCE = {
  title: 'A tour built around your work',
  description: 'Agent instructions for a live, context-aware tour, never a fixed demo deck.',
  steps: [
    'Use only user-authorized context already available in this client: current conversation, relevant memory/profile and connected integrations. Discover the current KANVAS template catalog and schemas; do not rely on a stale template list. Do not search unrelated private records just to personalize a tour.',
    'Choose two or three concrete uses relevant to this person: analytics for a data scientist, code/reviews for a developer, plans for a project manager, or calendars/maps for a trip. Adapt after each response instead of following a fixed script or prebuilt slides.',
    'If a connected database, warehouse or analytics source is available and authorized, consider a small read-only query and show its real result as a chart/table. State the source and freshness. Never invent live data or claim an unavailable integration is connected; clearly label any requested sample.',
    'When email/chat integrations are available, connect their use to inbox, email, chat and drafting. Calendar integrations pair with the read-only calendar; negotiated schedules use planner. KANVAS displays supplied data and does not itself query these services or send messages.',
    'Explain that Kanvas renders supplied content. Read current displays and revisions; publishing does not grant access or authority.',
    'Show one relevant view at a time when the tour is requested, using current source data and ordinary tools. Check actual delivery, invite a natural next step, and adapt to the user. Opening help alone does not authorize publication. Keep narration useful, not a tool walkthrough.',
  ],
};
export const HELP_PAGES:Record<HelpTopic,{title:string;description:string;steps:string[];example?:Record<string,unknown>}>={
tour: TOUR_GUIDANCE,
flashcards:{title:'Learn and self-test with flashcards',description:'Durable decks, one current card, screen or voice answers.',steps:['Publish template flashcards with cards [{id,prompt,answer,acceptedAnswers?}] and mode learn or test. A persistent deckId and deckRevision are assigned; replacing the screen does not erase progress.','Discover kanvas.flashcards.read to list saved decks or read a deck and its current card. kanvas.flashcards.show restores the latest saved state on a same-session display.','In voice mode ask the current prompt, then submit kanvas.flashcards.control action answer with the current cardId, response, display expectedRevision and expectedDeckRevision. Exact grading compares normalized supplied answers, not meaning; grading self records an explicit correct assessment, and none stores an ungraded response. Never claim semantic grading from exact matching.','Answer reveals without advancing; next/previous/reveal/restart are explicit actions. Retries reuse exactly the same requestId and input. Conflicts require reading current state. Progress is shared by the deck, not private per learner.']},
notifications:{title:'Optional new-session notifications',description:'Returning signed-in devices can explicitly opt into preview-free PWA push.',steps:['Open account defaults and choose Enable notifications on this device. Permission is requested only after this gesture. The installation must have configured push; unsupported browsers say so. On iOS/iPadOS use a Home Screen installation.','With active opt-in and no connected window or explicit target, account.begin can create a ready session and queue a notification. Otherwise it still asks the user to open Kanvas first. Only new owner sessions created by an agent, with a first display and no connected account screen, trigger notifications. Notifications contain no session title or content; clicking opens the authenticated display. Delivery is best-effort, not proof it was read.','Disable notifications in account defaults or sign out to revoke this browser subscription. Browser permission alone does not enroll a new account. A new sign-in must opt in again.']},
diagnostics:{title:'Safe browser troubleshooting',description:'A support reference links bounded first-party metadata to browser rendering.',steps:['Find the support reference in account defaults or the failed opening screen. Discover kanvas.diagnostics.read and supply supportRef to read your timeline. Cross-account access requires a configured service administrator.','Events contain only fixed categories, release, non-secret window/session/display/update IDs, revision and HTTP status; no view bodies, typed answers, error text, URLs, cookies, tokens or screenshots. Detail expires after 14 days and per-account caps may evict it earlier.','Startup events wait for account authentication before upload; failed boot before JavaScript or never-authenticated browsers cannot upload. Reporting failure never blocks rendering. Applied/render events are browser observations, not proof a person saw content.']},

"accounts-and-teams":{"title": "Profiles, organizations and independent teams", "description": "Optional photos, clear appearance precedence and explicit group access.", "steps": ["Open administration → Account & teams. Your profile photo is optional; PNG, JPEG or WebP images are resized locally and saved only when you confirm. You can also add a photo when registering or confirming email sign-in. Guests use a neutral silhouette.", "Create organizations or independent teams. A team may link multiple organizations; links never add members or grant access. Add existing accounts as members or administrators, or choose Invite a new member. A one-person group invitation lets its recipient create an account and explicitly join without later administrator follow-up. The group owner cannot be removed or demoted, and only the owner can manage administrators.", "For agents, kanvas_inspect groups.list/group.read and kanvas_access group.create/group.member.set provide the same account-wide management. Group changes require the current revision; use role:null to remove a member. Session-limited OAuth cannot manage account-wide groups.", "In session People & access, the owner can grant viewer/editor access to a team or organization. kanvas_inspect group-access.read returns revisions and kanvas_access group-access.set grants, changes or revokes with role:null. Membership is checked on every request. Individual or other group grants still apply after one grant is revoked.", "In session Settings, associate an organization/team for appearance separately from access. Precedence is session base → organization → team → explicit personal appearance → explicit session overrides. Empty overrides restore inheritance. Existing standalone sessions retain their settings. Branding is optional; personal theme does not remove a selected group logo/palette.", "Use kanvas_configure group.update, session-context.set or profile.update; inspect current data and revisions first. Groups establish ownership and collective permissions; no payment provider, subscription or charges are activated."]},
"activity-history":{"title": "Your activity history and access audit", "description": "Query actual retained events and create charts within your current permissions.", "steps": ["Console → Account & teams → Activity history shows your accessible account and session events. A session also has Activity → History & access audit. Filter by UTC date or event type; load earlier entries with the cursor.", "kanvas_inspect activity.read is a callable, paginated history tool, not a live snapshot. Include sessionId, groupId, since/until, type or afterId as needed. Current permissions apply to historical entries, including ended sessions. Removing access removes history access; selected-session OAuth cannot read unrelated or account-wide records.", "Access events record the actor, timestamp, affected group/session/member and before/after roles. Group administrators can inspect their group history. Entries do not retain message bodies, credentials, source documents or raw IP addresses.", "kanvas_inspect analytics.read returns real daily and event-type counts, plus a chart suitable for kanvas_publish show. Empty ranges return no chart rather than fabricated points. Records start with this feature; earlier session.log lifecycle data remains separate.", "The Service analytics tab and scope:service are restricted to deployment-configured service administrators. Session ownership alone grants no service-wide access. This layer includes aggregate account/group/session/display counts and coarse HTTP request/error/response-time buckets. Polling is not a unique visitor count.", "Activity retention is 365 days with a service cap of 100,000 events. HTTP aggregate retention is 90 days. Billing and unique physical-human counts must not be inferred from these measures."]},
"session-topology":{"title": "Live people, devices, browser windows and participant map", "description": "A live connection hierarchy, distinct from the chronological overview list.", "steps": ["Publish template session-topology in the intended session. groupBy:all (default, or displays) shows displays → people → devices → windows. groupBy:people and groupBy:devices select focused views. The agent chooses parameters; no on-screen grouping controls are added. A receiving browser stream, not a past registration, establishes connected state. Offline records are visually muted and retained for 30 days, up to 512 windows per session.", "Registered users use their optional avatar; guests use a differentiated silhouette. Devices use estimated phone/tablet/laptop/desktop/TV icons, with recognized browser logos per window. Viewport dimensions and join/last-seen times come from connection evidence. Browser profiles cannot prove a unique physical device or person.", "kanvas_inspect topology.read returns this hierarchy for agents. Only the session owner may request approximate GeoIP locations directly. Publishing includeLocation:true (or map layout) is also owner-authorized: it deliberately shares the approximate locations on that display with its authorized audience.", "Use layout:map with includeLocation:true for geographic plotting. expectedCountries such as [\"NO\"] highlights locations outside the expected countries; without a list, a different-from-majority country is a review hint. VPNs and network exits can appear elsewhere; this is never an automatic threat verdict.", "Locations use the existing local geoip-lite database, never an external per-IP lookup. Unknown location stays unknown. City/region/country and coordinates are approximate; an accuracy circle appears only when the database supplies a radius. This view does not collect GPS or retain raw IP addresses.", "This product includes GeoLite2 data created by MaxMind, available from https://www.maxmind.com. Browser logos retain their respective owners’ marks; third-party notices are included in the release."]},
"json-explorer":{"title": "Explore exact JSON as a tree", "description": "A structured explorer for nested source JSON, separate from code rendering.", "steps": ["Publish template json with data.json containing the original JSON source text, not a JavaScript object that may already have rounded its numbers. expandedDepth selects expansion from 0 to 64. expandedPaths and collapsedPaths are JSON Pointers; query selects matching keys/values and their ancestors.", "Ask the agent to expand, collapse or search, then publish the same exact JSON with new parameters. The compact tree has no search input, expand-all buttons or duplicate source footer.", "Integer and decimal tokens, duplicate object keys and reserved names remain intact. Values are rendered as text and never evaluated. The full source remains retained, including hidden branches; inspect display.current to recover it unchanged.", "Limits are 262,144 source characters, 12,000 nodes and 64 nesting levels. Malformed or over-limit JSON is rejected explicitly; it is not silently repaired or shortened."], "example": {"operation": "show", "requestId": "json-example", "view": {"version": 1, "template": "json", "data": {"json": "{\"count\":9007199254740993,\"rate\":1.2300,\"items\":[{\"ready\":true}]}", "expandedDepth": 2}}}},

  "account-start":{"title":"Start Kanvas on a connected screen","description":"A real KANVAS display, deliberate session choices and ordinary OAuth.","steps":["When the user asks to start/use Kanvas and no session is active in context, call kanvas_account_begin. It checks already-connected owned browser windows first, creates a fresh branded ready screen on the unambiguous selected window, and returns session/display IDs for publishing. With multiple windows choose one, never broadcast silently. With no connected window, an actively opted-in returning account may receive a started session and queued notification; publish to its returned IDs but never claim delivery or paint. If status is needs_display, ask the user to open only the returned bare startUrl (the configured public origin), sign in, then retry begin. The agent cannot physically open a user browser. Do not dictate long URLs or short session keys; existing direct session links continue to work.","Open the KANVAS root to see your account home: every session, New session and the account hub. Open /start to use this browser as a live screen. An unknown browser signs in by email; at /start a recognized account browser opens its own live Home display. Signup provisions a default session and display, and each additional registered device has its own Home target.","Home uses the normal overview template with scope:account and offers Gallery/List choices; layout:list is also agent-selectable for a compact recent-session list. Its recent-session choices come from the server; selecting a session and display is deliberate, never an automatic jump to the newest topic. Agents can read start.read or kanvas://start, then publish to the returned entry target like any other display.","The console is separate: follow consoleUrl (or the compatible adminUrl) returned by start.read. The public root is a receiving display surface, not the user console. The signed-out root also accepts a short session key without an account. Private viewer links offer equally explicit Sign in to my account and Pair this screen choices; pairing starts only after the viewer chooses it and still needs owner approval.","Connect agents to the ordinary protected /mcp endpoint. Its OAuth flow already verifies and provisions accounts. The former signup.begin operation is removed and /mcp/signup is retired; it must not be used as a second registration step.","Account sign-in is email-only with deliberate link confirmation; no password option is presented. A configured production email installation rejects the former password registration/login API. Email confirmation never silently grants an agent access: connector identity, requested scope and explicit consent remain part of OAuth.","Owners can rename a session with kanvas_session rename, current configRevision as expectedRevision, and name. Renaming preserves content, stable URLs, settings and access. Hosts decide when to invoke tools; the server cannot force an idle agent to run."]},
  "install-and-cast":{"title":"Install KANVAS and choose a receiving device","description":"An installable web app and account-registered browser receivers.","steps":["Open the root or /start and sign in. Chrome/Edge may offer Install app; iPhone/iPad Safari supports Share → Add to Home Screen. The installed app opens the same live Home surface.","The app needs a network connection. Only the offline explanation and icons are cached, never private views or account data. It does not add background AI activity or push notifications.","Sign in to KANVAS on each PC or TV browser. kanvas_inspect devices.read lists your registered devices, names, current display and last-seen time. Connected means an authenticated receiver is actually open; old registration alone is not online presence.","Use kanvas_control device.rename to give a receiver a useful name. Use device.present with deviceId, sessionId, displayId, the current device version as expectedVersion, and a unique requestId to place a permitted display on that device. device.present affects every connected window on that device. Use window.present with windows[].id and that window’s version to target just one tab while siblings stay unchanged. Identities survive reload and separate cloned tabs. Retry identical requests with the same ID; refresh the version for a new request.","A pending device command is not proof of display. devices.read reports applied for a window only after its bound receiver reports the target revision painted. Device-wide commands wait for every addressed window. Offline, revoked, expired or superseded commands are not successful casts.","kanvas_inspect participants.read with sessionId unifies active paired guests and registered account browsers across the session, including their display and last activity. Pairing approvals and offline device records are shown separately from actual presence.","Browser Cast, screen mirroring and AirPlay remain optional OS features. KANVAS does not discover unsigned-in TVs on the local network. A directly signed-in TV renders at its own dimensions; mirroring a phone reproduces its phone layout."]},
  'work-views':{title:'Read messages and technical work',description:'Source-driven email, inbox, chat, cards, bookmarks and developer/operations views.',steps:['email reads supplied messages with exact from/to/cc/subject/timestamp/body and thread boundaries. inbox is a read-only list of sender, subject, snippet, time and unread state, with paging and scrolling only. Rows do not open hidden messages. Prefer display names for inbox senders; inspect full/raw From headers before falling back to addresses. email, inbox and chat reject reply-style actions; use drafting separately when a draft is requested. Neither reads or sends external email.','chat shows exact sender/text/source time, optional contextLabel and conversationLabel for any platform, and an optional participants list. kanvas_publish chat.append appends messages with unique IDs, expectedRevision and requestId without resending the earlier thread. It follows the latest content only while the viewer is already at the end. No messages are sent to external services.','cards is a generic record board for issues, tickets, CRM items or tasks. Status labels and custom fields are free-form supplied values. Missing cost, access, approval or rollout data is not inferred.','bookmarks is an external URL collection, separate from retained KANVAS pins. Each bookmark has a preview action and a separate Open in new tab link. Cards and bookmarks size their columns using both viewport and content length. The new-tab link is activated by the viewer; browsers require user activation for reliable new tabs, so there is no claim that an agent can force a popup.','tool-inventory has an independently scrollable left integration rail and a right pane for the selected integration’s supplied tools. Set activeGroup when publishing or use navigation.control page to select a group; the right pane is the scroll target. tool-detail shows parameter names, types, required-input flags and returns. It is not code.tools execution and does not invent host permissions or approval status.','developer supports pull-request (files/checks/reviews), pipeline (stages/jobs), commits (actual supplied parent links) and review (code/line threads). operations supports environments, alerts, access, cost and rollout with supplied status records and stages. These do not call cloud or repository APIs or perform deployments.','code-workspace shows a file tree and supplied code/diff excerpt with an activePath. It stacks on narrow screens. The code tree also scales shallow/small structures larger, preserving scroll access to dense trees. Read template.get for exact contracts and examples.']},
  selection:{title:'Filter, sort and highlight source records',description:'Agent-authored presentation rules, without extra filter widgets.',steps:['Use kanvas_control selection.set with sessionId, displayId, expectedRevision, requestId and selection. Where conditions filter; sort gives stable multi-field ordering; highlight marks matching rows. No filter boxes, dropdowns or column-sort buttons are added.','Full source remains stored with the selection instruction. selection:null restores all rows in original order. Source values, numeric strings and record IDs are never overwritten. Same requestId and input can be retried; a new instruction needs the current revision. Held displays and permissions still apply.','Fields are literal keys or dotted paths such as fields.cost. An empty field addresses a scalar list entry. Use type number for exact decimal comparison including large decimal strings; invalid/missing numeric values sort last. Text comparison does not parse dates or currencies.','Collections: table.rows, list.items, log.entries, cards/inbox/bookmarks/operations.items, chat/email.messages, tool-inventory.groups, tool-detail.parameters; developer uses files, stages, commits or threads according to kind. Raw logs materialize derivative lines with stable original line numbers.'],example:{tool:'kanvas_control',arguments:{operation:'selection.set',sessionId:'session-id',displayId:'display-id',requestId:'cost-order-1',expectedRevision:4,selection:{sort:[{field:'fields.cost',type:'number',direction:'desc'}],highlight:[{field:'status',op:'eq',value:'needs review'}]}}}},

  'shared-pointing':{title:'Point together at the same content',description:'Optional named semantic markers that follow text and data across screen sizes.',steps:['Shared pointing is off by default. The session owner can explicitly enable it with kanvas_access pointing.configure: sessionId, enabled:true, confirm:true and expectedRevision from kanvas_inspect pointing.read (initially 0). Disable the same way with the current settings revision. This does not enable public access or change participant permissions.','An authorized receiving browser then shows Point. Each person opts into local pointing mode; tap a word, data cell, chart mark or image, or drag a short text span. Done pointing or Escape restores normal interaction. Markers carry the account or approved participant name, never a client-supplied identity.','Text uses a logical span, tables use the original source row and column, and chart marks use their data identity. Each receiving browser resolves that anchor in its own layout. Images use coordinates relative to the image itself, excluding letterboxing. A target that is not on the current page is not moved or guessed.','Each participant has one replaceable pointer per display, expiring after 20 seconds. Disabling the feature, revoking a participant or replacing the view clears affected markers. Source content, stored history, zoom and layout stay untouched. Embedded external pages, custom HTML, games and video do not expose semantic targets. Public anonymous readers do not participate.']},
  images:{title:'Show full images, team logos and drawing backgrounds',description:'Source-preserving media with optional per-image information.',steps:['Publish image-gallery with data.images:[{url,alt?},…], mode:grid or carousel, and optional columns from 1 to 8. Up to 20 images remain uncropped with aspect ratios intact. Grid is the default. Carousel supports local swipe on public and signed-in screens. Broadcast navigation.control page commands synchronize public viewers, including reload; viewer-targeted commands remain private. Tap a grid image for a temporary enlarged view, then Back to gallery; source and history are unchanged.','Each image may supply title, caption and source:{title,url?}. These remain hidden unless its showTitle, showCaption or showSource is explicitly true. No captions or source labels are invented.','Scoreboard sides and standings rows accept logo:{url,alt?}. The scoreboard sizes all 2–16 sides to the available screen. Logos keep their aspect ratios without changing names, exact scores or standings values.','Use a safe source URL or import actual PNG, JPEG, WebP or SVG bytes with asset.import. SVG imports support passive shapes, text, local gradients and clips; scripts, external/embedded content and animation are rejected. Uploaded images remain session-scoped, including explicit public-view asset permissions.','A whiteboard may include background:{url,alt?,x?,y?,width?,height?}. Its default world rectangle is 0,0,1000,600. The image is painted behind every drawing element and preserved when drawing or saving. Omitting background keeps the ordinary blank whiteboard.']},
  feedback:{title:'Report an issue at the right scope',description:'Separate session observations, private account feedback and general service requests.',steps:['Offer feedback once when users hit errors, workarounds or confusion; file only on request or consent. Never include private content or credentials, and do not nag.','Use kanvas_feedback submit or error.report with requestId, title and description. scope:session is the compatible default and requires sessionId. Related display/update/diagnostic IDs belong only to that session.','For an account-specific issue use scope:account without sessionId. For a general KANVAS service request use scope:service without sessionId. Account-wide authorization is required; selected-session connector grants do not expand.','kanvas_inspect reports.read uses the same scope and paginates nextCursor as afterId. Account reports are private to their account, service reporters can read their own submissions, and configured service administrators can query service reports or scope:all for the unified log. Unified review visibility does not grant access to other session content.','The console Feedback & error reports screen offers explicit compose and list scopes. Current session owners review their session reports, account owners review their own account reports, and service administrators review service requests. Every review needs current expectedRevision and an evidence-based note.','KANVAS MCP calls are logged automatically in the persistent tool-call feed with unique IDs, timestamp, tool, operation, authorized session, result status and duration; raw inputs, results and secrets are not stored. Read tool-log.read without sessionId for private account-level calls, or with it for that authorized session. External integrations may optionally append actual events.']},
  about:{title:'What is Kanvas?',description:'A persistent visual work surface for AI agents: connect a browser first, then show and work with your information.',steps:['Kanvas is a persistent display workspace controlled through MCP. It shows text, lists, charts, documents, media, comparisons and interactive views on a connected screen. It does not fetch your calendar, email or other external data itself.','Recognize first contact: no active session, no known target, or a user asking what Kanvas is or requesting a first demo. Start with the connection, not a long session URL. Read kanvas.account.begin and kanvas.devices.read; no active session is required for a signed-in idle receiver to appear.','Say to the human (voice or text): Open a browser on the screen you want to use, go to kanvas.host, and sign in with your email. The root shows email sign-in and short session-key pairing when signed out, and the account session overview when signed in.','Agent operations: reuse an authorized existing session when relevant; otherwise submit user-authorized content. Choose an unambiguous connected owned window and call kanvas.window.present with its current version and the returned session/display IDs. Use kanvas.device.present only when all connected windows on that device are intended. Check actual painted receipts, not just a pending command. Ask about the intended screen only when genuinely ambiguous.','If the device path is unavailable, offer the returned shortUrl as a clickable link or short session key. Never read a long view URL aloud. Pairing a guest still needs explicit owner approval; a short key is not authorization.','Continue with kanvas.help.getting-started.steps for the operational checklist and kanvas.help.submit for the submit envelope. Opening help alone does not authorize a publication.']},
  'what-is-kanvas':{title:'What is Kanvas?',description:'A persistent visual work surface for AI agents: connect a browser first, then show and work with your information.',steps:['Kanvas is a persistent display workspace controlled through MCP. It shows text, lists, charts, documents, media, comparisons and interactive views on a connected screen. It does not fetch your calendar, email or other external data itself.','Recognize first contact: no active session, no known target, or a user asking what Kanvas is or requesting a first demo. Start with the connection, not a long session URL. Read kanvas.account.begin and kanvas.devices.read; no active session is required for a signed-in idle receiver to appear.','Say to the human (voice or text): Open a browser on the screen you want to use, go to kanvas.host, and sign in with your email. The root shows email sign-in and short session-key pairing when signed out, and the account session overview when signed in.','Agent operations: reuse an authorized existing session when relevant; otherwise submit user-authorized content. Choose an unambiguous connected owned window and call kanvas.window.present with its current version and the returned session/display IDs. Use kanvas.device.present only when all connected windows on that device are intended. Check actual painted receipts, not just a pending command. Ask about the intended screen only when genuinely ambiguous.','If the device path is unavailable, offer the returned shortUrl as a clickable link or short session key. Never read a long view URL aloud. Pairing a guest still needs explicit owner approval; a short key is not authorization.','Continue with kanvas.help.getting-started.steps for the operational checklist and kanvas.help.submit for the submit envelope. Opening help alone does not authorize a publication.']},
  planner:{title:'Edit and finalize a visual plan',description:'Use kanvas.planner operations for targeted changes; committing never syncs calendars or sends invitations.',steps:['Get kanvas.template.planner for the initial view. After kanvas.submit use kanvas.planner.read, kanvas.planner.edit, kanvas.planner.propose, kanvas.planner.review and kanvas.planner.finalize instead of reconstructing the entire plan. Get each operation schema, preserve item/proposal IDs, and use current expectedRevision and unique requestId values.','Immediately after committing, tell the user: Your plan is committed within Kanvas as a visual/organizational artifact only. No Google Calendar, Outlook, calendar invitations or emails have been updated or sent.','Offer real-world changes only as a separate explicit next step the user asks for and agrees to, using the calendar/email tools available to the agent. Kanvas is not a calendar sync or automation engine.']},
  orientation:{title:'Kanvas Help',description:'Get a useful visual onto a screen, then work with it together.',steps:['First-time user or no active screen: read kanvas.help.about, then kanvas.help.getting-started.steps. Tell the human to open kanvas.host, sign in and leave that screen open; use the connected receiver rather than reading a long session URL.','KANVAS is a persistent display workspace controlled through MCP tools. It can show text, lists, charts, documents, media, comparisons and interactive views.','Start with your task: show something, work with an existing view, or share a screen. Ask for a focused how-to when needed.','Opening Help only returns guidance. It does not publish a deck, create a session, or change an existing display. Choose an activity if you want a hands-on example.']},
  reading:{title:'Read comfortably at your own pace',description:'Independent text size, zoom and words-per-minute controls for document reading.',steps:['Publish document with layout reading. Automatic scrolling starts paused. Use the reading toolbar or navigation.control with navigation.action reading.','Commands are start, pause, resume, slower, faster and configure. The default is 220 words/minute; slower/faster use 120, 160, 190, 220, 260 and 320. Explicit wpm accepts any integer from 120 to 320. Actual scrolling uses the rendered document geometry.','fontSize accepts 16–40 pixels; zoom accepts 0.75–1.75. Both are independent from wpm. Pause retains your position. Touch or wheel interaction pauses automatic reading. Background tabs do not advance.','Use Save my defaults, or saveDefaults:true with the particular fields you intend to save. Account defaults merge text size, speed and zoom independently. New documents and sessions inherit them but never start scrolling automatically. Guest screens cannot save an owner’s personal defaults.','Source text, numeric strings, publication revisions and history are not rewritten by reading controls. Viewers report the observed size, speed, zoom, position and playing state.'],example:{tool:'kanvas_control',arguments:{operation:'navigation.control',sessionId:'session-id',displayId:'display-id',requestId:'read-pause-1',expectedRevision:3,navigation:{action:'reading',command:'pause',wpm:190,saveDefaults:true}}}},
  'task-updates':{title:'Show task progress and exact logs',description:'Accumulate real milestones, inspect dense logs and use proportional timelines.',steps:["The session content overview defaults to a thumbnail grid; layout:list and showPreviews:false are available. It renders retained source previews, not historical screenshots. Account-wide session choices stay a compact list.","Autoplay start uses intervalSeconds:5 when omitted. Any interval from 0.25 through 86400 seconds is accepted; faster sequences should be explicitly requested. pause, resume and stop retain the current playlist.",'Use progress for a live task: task, orientation (horizontal by default or vertical), status and events. Each event has a unique id, title, ISO timestamp, status and optional description. Use only completed observations or genuinely running work; do not invent progress to fill the view.','After publishing, kanvas_publish progress.append accepts exactly one event plus sessionId, displayId, expectedRevision and requestId. Existing events are retained server-side. Timestamp may be omitted on an append to use server time. Retry identical arguments and requestId after a lost response; read current revision before a different event.','Progress events use a continuous straight spine with perpendicular connectors. layout:auto alternates six or more events around a centered line when space permits; layout:alternating explicitly requests both sides and layout:single keeps all cards on one side. Both horizontal and vertical orientations support the choice. Event timestamps remain exact; static timeline keeps proportional time positions. Static timeline remains distinct and supports start/end durations. Large histories scroll rather than truncate.','Use log with exact raw text or structured entries, not both. Structured entries allow line, timestamp, level, message, flagged and annotation. Levels are trace, debug, info, warn, error and fatal. startLine and pageSize control references and paging.','Click a log line to send revision-bound log.inspect context to interactions.read. Search highlights within the normal surrounding lines; source whitespace and numbers are not rewritten.','Overview uses a compact retained-view list with optional showMetadata. Selecting a row browses that exact retained view without rewriting source content; full-account browsers can also return Home or sign out.'],example:{tool:'kanvas_publish',arguments:{operation:'progress.append',sessionId:'session-id',displayId:'display-id',requestId:'browser-complete-1',expectedRevision:4,event:{id:'browser-complete',title:'Receiving browser verified',status:'completed'},status:'completed'}}},
  invitations:{title:'Invite someone to KANVAS',description:'Create a welcome link without granting private access or sending a message.',steps:['Use Invite to KANVAS in the workspace, or kanvas_access invite.create with requestId and an optional label. The result contains a welcome URL and a pasteable introduction. Nothing is sent automatically.','For organization/team membership, pass groupId. Only a current group administrator may issue it. The single-use welcome link has an unguessable ID. The recipient signs in or verifies their account and explicitly chooses Join, or authorizes invite.accept with confirm:true. Inviter authority is rechecked, existing higher roles are retained, and linked groups are not joined. Use invite.revoke to invalidate an unused link.', 'General invitations are independent of sessions, pairing and games. Recipients sign in or create their own account. Opening an invitation never adds membership or approves a receiving browser.','New random locators use four lowercase alphanumeric characters excluding ambiguous o, 0, i, 1 and l. Existing links and canonical IDs are preserved. Locators are not credentials.','Optional custom addresses use kanvas_session address.customize, owner authority and an operator-enabled entitlement. Choose 5–32 lowercase alphanumeric characters beginning with a letter; null releases the custom locator. This is not a payment or subscription system.']},
  submit:{title:'Submit your first view with kanvas.submit',description:'kanvas.submit sends a prepared view or source data to a connected screen; get its operation schema before calling.',steps:['Use kanvas_publish with operation show, a unique requestId and either a prepared view or exact source context/data plus intent. Do not invent facts to populate an example.','For a deliberately new topic, supply newSession:true and a sessionName. Continue using the returned targetRef, or explicit sessionId and displayIds. If needs_target is returned, resolve that choice; never select another topic merely because it is recent.','Prefer device/window present to the connected signed-in screen. If a link is necessary, return shortUrl first; only use viewerUrl if no short URL is available. These URLs locate a display, not grant access. No QR or guest approval is needed for the signed-in owner.','Read kanvas_inspect operation update.status. Prepared means saved; applied means a receiving browser reported rendering. A server snapshot is a separate verification.'],example:{tool:'kanvas_publish',arguments:{operation:'show',requestId:'first-list-1',newSession:true,sessionName:'Trip checklist',view:{version:1,template:'list',data:{ordered:false,items:['Passport','Tickets','Charger']}}}}},
  navigation:{title:'Navigate, restore history and autoplay prepared views',description:'Page, scroll, find, highlight and focus without republishing source data.',steps:['Execute explicit user requests to scroll, page or navigate immediately; never refuse based on pageCount/matchingItems or inferred visibility. Those counts are logical pagination. navigation.read returns fresh per-viewer viewport measurements; null means unknown, not no overflow.','Presentation/procedure gestures take precedence over session history; table horizontal scrolling, map dragging, JSON tree keys and editable inputs keep their native behavior. At an internal boundary, history browsing is local only and never propagates through display sync.','A notes presentation can set data.presenterPreview:true for private browsing. Go live explicitly pushes its previewed slide to linked screens; Follow live resumes the published position. Audience navigation chrome is hidden by default; showControls:true reveals it per published display. Notes retain their own controls.','For server-driven carousel/kiosk playback, open Displays → Autoplay / kiosk or use kanvas_control autoplay.control. Start with current expectedRevision, requestId, intervalSeconds from 2 to 86400 (including fractional values), and loop true/false. It plays the current prepared presentation, or snapshots the supplied frames from authorized displays/history in the same session. Only supplied frames are played. Inspect autoplay.read, then pause/resume/stop with sessionId, displayId, action and a fresh requestId. Optional expectedVersion or runId rejects stale commands. State survives restart; newer content, holds and lost editor access stop it. Stop preserves the last frame; queued/running is distinct from confirmed browser paint.','Arrow keys and horizontal swipes page within the current view first, then step through retained session frames in publication order. Reverse entry starts at the last inner page. Home and End choose first/last frame; Session overview in the display menu opens the positional overview list. Escape is not bound to session navigation. PageUp/PageDown retain native scrolling. Private browsing does not restore shared history, change the other viewers, or acknowledge unseen new content. Use Back to live to resume the published display. ' ,'Read display.current and navigation.read for the selected display revision and capabilities. Send kanvas_control operation navigation.control with requestId, expectedRevision and navigation. Page numbers start at 1.','Navigation actions: page (direction next/previous or page), scroll (normalized x/y or deltaX/deltaY), search (query), match (next/previous), highlight (text), focus (text or normalized region and zoom), gotoLine (absolute displayed line in code kind, respecting startLine), fit (whole org-chart/flowchart/network/architecture diagram), reset. Match navigation applies to the currently rendered text. Tables and lists search their entire supplied collection and reset to page 1.','Independent is the default: viewers browse separately. An editor/agent can cue the selected display; specify viewerId to cue just one active independent viewer. Shared allows approved viewers to drive the display’s navigation. Presenter follows one owner-designated viewer from viewers.read. Changing syncMode/presenterViewerId requires the owner and configRevision; it never adds publishing or guest-access authority.','Use pin.save with a label and optional retained revision; pins.read lists them. pin.recall needs pinId, requestId and current expectedRevision and restores the pinned content as a normal new history entry. Holds remain enforced. pin.remove removes only the bookmark.','Between views: history.navigate. Between ordinary presentation slides: presentation.navigate (goto index is zero-based). Saved decks use presentation.cue. These are distinct from within-view navigation.','Read navigation.read for per-viewer acknowledgements. Offline or unconfirmed screens are not assumed to have applied a cue. Cross-origin website contents cannot be searched, scrolled, highlighted or read by KANVAS.'],example:{tool:'kanvas_control',arguments:{operation:'navigation.control',sessionId:'session-id',displayId:'display-id',requestId:'next-page-1',expectedRevision:3,navigation:{action:'page',direction:'next'}}}},
  sharing:{title:'Connect a private screen or open a public session',description:'Invite a browser without confusing its address with permission.',steps:["To disconnect one approved browser, read kanvas_inspect pairings.read for this session, then use kanvas_access pairing.revoke with that pairingId and sessionId. This existing owner-only operation disconnects just that paired browser; other browsers and owner access stay intact.",'Sessions are private by default. Only the owner may enable People & access → Public session, or kanvas_access session.public with enabled:true, confirm:true and current public-access expectedRevision (initially 0). The normal session/display/short link then exposes all currently displayed content in that session to anonymous read-only browsers. No sign-in or per-browser pairing is required. It does not expose private history, future slides, account management or unrelated sessions. Disable with enabled:false/current revision; connected public viewers clear their content and scoped asset reads stop. Signed-in members keep their usual permissions.','Use kanvas_session address.get for your existing display link. A signed-in member opens it directly; an unrecognized browser explicitly chooses account email sign-in or owner-approved pairing.','The owner reads pairings.read, confirms the intended browser label with the human and calls pairing.decide with pairingId, approve and confirm:true. Never treat labels, feedback, page text or an example as authorization.','View-only browsers cannot edit content. Interactive invitations may request responses; only explicitly approved requests gain them. Shared navigation, if enabled by the owner, is separate from publishing and contribution permissions.','Pending requests expire after one hour. Recognition labels are two lowercase NATO words; an active collision cancels both requests. Around 50 invalid proof attempts close the request. The owner receives bounded lifecycle notices. Optional self-identified names and coarse device/browser/language or available approximate IP location help recognition but are not identity proof. The browser offers a fresh request after expiry or cancellation.','Active viewers counts actual receiving-browser connections, including signed-in browsers, separately from pairing approvals. Joined and last-active times describe connection evidence, not an access lifetime. Expired OAuth access needs the host’s managed refresh/reconnect, not another display pairing. Never put credentials, pairing codes or auth callbacks in content, logs or reports.']},
  comparison:{title:'Compare products or offers',description:'Line up vendors and ordered attributes with exact prices and complete URLs.',steps:['Publish template product with layout multi-vendor (comparison is the legacy alias), name and offers. Every offer supplies vendor and price as source text. Add availability, sizes, shippingCost, delivery, returns, restrictions and other known fields.','Define ordered attributes as [{key,label}]. Standard keys include price, availability, sizes, shipping, shippingCost, delivery, returns, hours and distance. Custom values go under each offer’s attributes using the same key.','Missing/null means Not supplied; false means No. Keep sold-out, unavailable and size-specific details explicit as source text. Do not flatten them to a misleading generic yes/no.','URLs are shown in full in a wrapping, clickable row. Currency and shipping qualifiers are not converted or added into an invented total. Use horizontal/vertical navigation for larger matrices. Existing image-led and compact layouts remain available.'],example:{version:1,template:'product',data:{name:'Running shoe offers',layout:'multi-vendor',attributes:[{key:'price',label:'Price'},{key:'sizes',label:'Sizes'},{key:'delivery',label:'Delivery'}],offers:[{vendor:'Vendor A',price:'NOK 1,499',sizes:'EU 42 only',delivery:'3–5 days; Norway',url:'https://example.com/offer-a'},{vendor:'Vendor B',price:'EUR 119',url:'https://example.org/offer-b'}]}}},
  iframe:{title:'Show external websites',description:'Edge-to-edge public pages, optional mobile viewports and honest static fallbacks.',steps:['Publish template website (iframe remains a compatible alias) with data.pages:[{url,title?,viewport?},…], layout paged or grid, and optional zero-based index. Grid is the default and shows all 1–16 pages, including a two-by-two layout for four. There is no top transport toolbar. An explicit paged layout loads the active page and uses navigation.control for page changes. Set viewport mobile per page for a scaled 390×844 layout; desktop is the default. Mixed viewports work in one grid.','Use an ordinary public HTTPS URL. Empty collections, more than sixteen pages, credentials in URLs, local/private literal addresses and executable schemes are rejected.','Third-party pages run in a sandbox. Their own CSP frame-ancestors and X-Frame-Options remain authoritative; KANVAS never strips headers or proxies a page to bypass embedding restrictions. Some sites also require features unavailable in the sandbox.','When response headers actually forbid framing, KANVAS attempts a bounded, anonymous server screenshot of the public page. It uses no viewer cookies or sign-in, blocks private networks and does not strip framing headers. Set screenshotFallback:false to disable it. Captures are labelled static with their timestamp and expire after ten minutes; they are not interactive. A frame load or screenshot never proves that a remote page rendered on a person’s screen. If capture fails, a visible original-link card shows available public title/description/preview image and explains the failure. Remote contents remain unverified. Original links remain available. Cross-origin text/DOM, search and remote controls are not accessible.','The visible name and primary template ID are Website and website. The iframe ID remains a compatible alias. It replaces web in current public discovery. Stored web snapshots, summaries and allowlisted embeds still render from history; exports retain their legacy data. New public submissions use website. Custom html stays script-free and does not gain iframe permission.'],example:{version:1,template:'iframe',data:{pages:[{url:'https://example.com/',title:'Example'},{url:'https://www.iana.org/help/example-domains',title:'About example domains'}],index:0}}},
  regional:{title:'Set numbers, units and dates',description:'Use regional display preferences without changing exact source strings.',steps:['Use kanvas_configure session.update with sessionId, expectedRevision and config. numberLocale accepts BCP-47 locale tags such as nb-NO, de-DE or en-US. unitSystem is source, metric or imperial. dateFormat is source, dmy, mdy or iso. timeFormat is locale (default), 12h or 24h. timeZone is an IANA zone (empty uses the viewing device). Precedence: view.format, session config, account defaults inherited by new sessions, then viewing device. Explicit calendar/clock zones retain their meaning. A view.format object can override dateFormat/timeFormat/numberLocale/timeZone without changing stored ISO source values.','Account defaults use preferences.update and its own revision; new sessions inherit them. Existing sessions change only when configured.','Numeric values use the chosen number locale. Exact text, numeric-looking strings, identifiers, currencies and precision-sensitive decimals stay as supplied.','Weather converts only explicitly qualified C/F values or numeric temperature text accompanied by data.temperatureUnit (celsius/fahrenheit). Unqualified values remain unchanged. Other units are not guessed.','Date preferences reorder supported date fields without changing their calendar day or supplied timezone. Raw transcript and source text remain untouched.']},
  templates:{title:'Choose a template',description:'Use the current catalog and exact field schema instead of guessing.',steps:[VERBATIM_SOURCE,'Template get returns relatedOperations for stateful workflows. After initial kanvas.submit, use planner, checklist, draft, presentation, timer or other dedicated operations with authoritative state and revisions instead of reconstructing complete data arrays. Get each linked operation schema before calling. Planner commitment remains visual only; read kanvas.help.planner and tell the user no external calendar or email was changed.','Template refinements: device-preview gridSize compact shrinks only frame tiles; code kind split shows 2–3 code/diff panels, navigation gotoLine accepts panelId and side before/after. Itinerary list items accept inlineMap {points:[{lat,lng,label?}],connect:true} with one or two pins on a generalized network-free thumbnail; straight connections are not routes. For itinerary map use navigation selectDay with day 1..N or all; read returns selected day. Map contentDisplay permanent is supported globally/per marker; popupHtml allows passive structural HTML and allowlisted inline styling, never scripts/stylesheets or CSS URLs.', 'For roster/schedule planning, ask for missing blocked dates, mandatory days off, holidays and shift constraints, then soft preferences such as consecutive blocks and longer recovery breaks before the first draft. Reuse constraints already given. During iterative edits identify recurring preferences, summarize them tentatively, confirm with the user and offer to save preferences (not shift/person data) using the agent memory system. Kanvas visualizes supplied rosters; it does not optimize or invent assignments.','calendar is a read-only day/three-day/week/month event grid, distinct from planner proposals/commitments and schedule agenda/month/year overviews. Both calendar and planner accept supplied hourly weather for day/three-day/week, including optional wind and sunrise/sunset markers in the same strip; KANVAS fetches nothing.',"New reading views: record-detail preserves identity, status, assignees, arbitrary fields, description, activity and typed related links. story-cards contains only optional images, headlines and short summaries. Cards may use an explicit hex statusColor; no colour semantics are inferred. Recipe has an optional image and per-step stepDetails images/action icons; itinerary events accept optional category icons. Scoreboard event is an optional one-line text/type/sideId.",'kanvas_inspect template.get returns a template’s complete schema and display guidance (illustrative examples are omitted only when needed to retain the full composite schema). Use the public template index in these docs for discovery.','scoreboard shows two or more freeform numeric/text sides with optional period/clock/context. Authorized interactive viewers can tap plus/minus; editors use scoreboard.control with sideId, current expectedRevision, requestId and action increase/decrease/set (set requires score). Public and read-only viewers cannot change scores. standings has freeform columns, supplied ranks/movement and multiple groups; agent-selected sort preserves exact numeric strings and supplied positions. tool-call-log is a persistent newest-first list of automatically recorded KANVAS MCP calls and optionally supplied external calls, with adjacent same-tool repetitions folded and expandable. External events may be appended using kanvas_publish tool-log.append with stable event IDs, integration/tool and actual timestamp. tool-log.read paginates retained records; KANVAS calls are automatically captured server-side with tool, operation, time, status and session, without raw arguments/results or invented metrics.','device-preview compares static HTML/CSS across labelled CSS viewport frames, with representative presets and exact custom dimensions; Actual size supports 1:1 inspection. Not hardware or email-engine simulation. architecture describes typed service/database/api/queue/cache/external/client/load-balancer nodes and directed edges. code kind terminal is a read-only command transcript, not a shell: entries contain id, command, stdout/stderr, status, exitCode, timestamp and cwd; publish patch/replace updates append output. sports-lineup shows supplied soccer players on a pitch using normalized x/y positions. org-chart uses parentId and top-down/left-right hierarchies. flowchart uses connected box/decision/terminal nodes. network accepts arbitrary directed/undirected edges and optional positions. Read their schemas and examples; no data or connections are inferred.', 'Common choices: fact for concise text; number/KPI for a metric; list for ordered/unordered items without checkboxes; checklist for completion state (publish patch op:checklist with itemId, action add/remove/update/move, value text/detail/checked and optional beforeId; current expectedRevision and requestId required); table for rows; chart for numeric source data; product layout multi-vendor for one identical product at several sellers; standalone comparison for distinct items. Roster edits use kanvas_publish patch operations {op:roster,action:add/remove/update,date,shift,person?,value?}, retaining unrelated assignments; showDayCounts adds per-day shift summaries.','Optional data.emphasis decorates table/comparison row and/or column, or chart series plus zero-based point index. referenceLines adds supplied y targets to Cartesian charts. Table columns may be omitted with positional row arrays for a headerless grid; use meaningful headers for true columns. Choropleth regions accept countryCode (ISO alpha-2/alpha-3 or US-XX) instead of geometry, backed by Natural Earth 110m; small territories use approximate point markers; unsupported codes are skipped with an on-map warning and can be supplied as explicit GeoJSON.', 'Table rowStyles/cellStyles set arbitrary RGB hex backgrounds and optional text colours. Address rows by their zero-based retained source index; a cell also names its column. Inline indicators support labelled dots, built-in icons or authorized image/logo URLs. These decorations never change the source values and follow rows through filtering and sorting.', 'Documents, transcription and translation retain supplied source text. Translation mode chooses the translation layout unless a template is explicitly requested.','Native video and recognized YouTube/Vimeo URLs use video, not iframe. Provider readiness is not playback. Read actual command outcomes; blocked autoplay may need a viewer tap.','Titles, sources, captions and extra controls are opt-in. There is no source.illustrative field or automatic sample badge. If sample text should be labelled, put that label in the supplied content. Other provenance remains available.']},
  recovery:{title:'Recover from a failed call',description:'Find the real error, correct the input, and retry without duplicating work.',steps:['Read server.version/profile/counts in tool results. Refresh the host’s cached tool catalog after an upgrade.','Required fields are listed first in each public tool description. Supply native booleans, numbers, arrays and objects; one JSON-encoded layer is tolerated only for schema-known non-text fields. Literal source text stays literal.','Use the operation-specific recovery.get pointer and bounded example returned with validation errors. For kanvas.submit, view wraps version/template/data; displayIds is an array, and the optional view title is beside data (template-specific fields stay in data). Preserve source and authorization rather than blindly copying example IDs. Use the returned field issue/schemaTool to fix invalid arguments. If the host hides error text, session.state includes recent safe diagnostics. Do not infer that every write is denied from one validation error.','For a lost response, retry the identical requestId and arguments. For a new action after a revision conflict, read current state and send a new requestId. Never blindly overwrite a newer view.','Media failures distinguish network, decode, source rejection, timeout and provider refusal. Source rejection alone does not prove CORS or a codec problem. An unavailable remote website/clip needs an available source.','Use feedback submit for suggestions, error.report for reproducible failures. Prose reproduction is accepted within its documented limit; reports persist separately from interactions. Never include credentials.']},
  'agent-workflow':{title:'Use Kanvas Help with an agent',description:'Learn a user-chosen task with live context and real interaction.',steps:['Respond to the intent of a request for help, not a keyword trigger. Use help.read with a focused topic/question and optional authorized session/display context. A general request gets a short orientation and a few choices; a specific how-to gets the relevant recipe.','Do not publish anything merely because Help was opened. Once the user requests an activity, use normal publishing/control tools within that authorization without repeatedly asking to perform routine steps.','Use the agent host’s available search or domain tools only where the task benefits from them. Attribute supplied sources; if tools/data are unavailable, say what is missing instead of silently inventing live facts.','Branch with the user’s choices and existing session state. On reconnect, read current view and pending interactions; do not start a fixed sequence. Read and acknowledge actual interaction IDs once, and verify receiving-browser outcomes before describing success.','For a personalized walkthrough, read help topic tour or guide topic tour: use available authorized memory/profile and connected tools to construct a relevant live experience.', 'For “what is Kanvas?” or “show me what you can do”, compose a live answer from the current tool descriptions, template list and guides (guide.get, template.get, help.read) and publish real, relevant views. There is no fixed or pre-built demo deck.','MCP guidance cannot force host tool loading, idle-agent wakeups, narration style or auto-approval. User intent and existing permission remain authoritative.']},
};
export function helpFor(topic:HelpTopic,publicUrl:string,question?:string){const page=HELP_PAGES[topic],root=`${publicUrl.replace(/\/$/,'')}/docs/`;return {name:'Kanvas Help',version:KANVAS_VERSION,topic,...page,question,published:false,docs:{primary:root,topic:`${root}${topic}`,markdown:`${root}${topic}.md`,index:`${root}index.json`},...(topic==='orientation'?{choices:['Show something','Work with the current view','Share a screen']}:{}),agentInstruction:'Use this task-focused guidance with the user’s intent and live authorized state. Opening Help is not a request to publish. When an activity is authorized, carry it out with normal tools and real input/receipts; no fixed deck or repeated routine confirmations.'};}
